/* Generated from marshmallow.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='marshmallow'],
[data-ui-theme='marshmallow'] {
  color-scheme: light;
  --ui-background: oklch(0.97 0.01 264.53);
  --ui-foreground: oklch(0.22 0 0);
  --ui-card: oklch(1.00 0 0);
  --ui-card-foreground: oklch(0.22 0 0);
  --ui-popover: oklch(1.00 0 0);
  --ui-popover-foreground: oklch(0.22 0 0);
  --ui-primary: oklch(0.80 0.14 349.25);
  --ui-primary-foreground: oklch(0 0 0);
  --ui-secondary: oklch(0.94 0.07 98.08);
  --ui-secondary-foreground: oklch(0 0 0);
  --ui-muted: oklch(0.92 0.01 268.52);
  --ui-muted-foreground: oklch(0.34 0 0);
  --ui-accent: oklch(0.83 0.09 248.95);
  --ui-accent-foreground: oklch(0 0 0);
  --ui-destructive: oklch(0.70 0.19 23.19);
  --ui-destructive-foreground: oklch(0 0 0);
  --ui-border: oklch(0.85 0 0);
  --ui-input: oklch(0.85 0 0);
  --ui-ring: oklch(0.83 0.09 248.95);
  --ui-chart-1: oklch(0.80 0.14 349.25);
  --ui-chart-2: oklch(0.77 0.15 306.21);
  --ui-chart-3: oklch(0.83 0.09 248.95);
  --ui-chart-4: oklch(0.88 0.09 66.27);
  --ui-chart-5: oklch(0.94 0.14 130.35);
  --ui-sidebar: oklch(1.00 0 0);
  --ui-sidebar-foreground: oklch(0.22 0 0);
  --ui-sidebar-primary: oklch(0.80 0.14 349.25);
  --ui-sidebar-primary-foreground: oklch(0 0 0);
  --ui-sidebar-accent: oklch(0.83 0.09 248.95);
  --ui-sidebar-accent-foreground: oklch(0 0 0);
  --ui-sidebar-border: oklch(0.85 0 0);
  --ui-sidebar-ring: oklch(0.83 0.09 248.95);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Gabriela', ui-serif, serif;
  --ui-font-heading: 'Gabriela', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Geist Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 2px 5px 0px oklch(0.83 0.09 248.95  / 0.05);
  --ui-shadow-panel:
    0px 2px 5px 0px oklch(0.83 0.09 248.95  / 0.10), 0px 4px 6px -1px oklch(0.83 0.09 248.95  / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='marshmallow'].dark,
[data-ui-theme='marshmallow'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.22 0 0);
  --ui-foreground: oklch(0.97 0.01 264.53);
  --ui-card: oklch(0.29 0 0);
  --ui-card-foreground: oklch(0.97 0.01 264.53);
  --ui-popover: oklch(0.29 0 0);
  --ui-popover-foreground: oklch(0.97 0.01 264.53);
  --ui-primary: oklch(0.80 0.14 349.25);
  --ui-primary-foreground: oklch(0.22 0 0);
  --ui-secondary: oklch(0.77 0.15 306.21);
  --ui-secondary-foreground: oklch(0.22 0 0);
  --ui-muted: oklch(0.32 0 0);
  --ui-muted-foreground: oklch(0.85 0 0);
  --ui-accent: oklch(0.83 0.09 248.95);
  --ui-accent-foreground: oklch(0.22 0 0);
  --ui-destructive: oklch(0.70 0.19 23.19);
  --ui-destructive-foreground: oklch(0.22 0 0);
  --ui-border: oklch(0.39 0 0);
  --ui-input: oklch(0.39 0 0);
  --ui-ring: oklch(0.83 0.09 248.95);
  --ui-chart-1: oklch(0.80 0.14 349.25);
  --ui-chart-2: oklch(0.77 0.15 306.21);
  --ui-chart-3: oklch(0.83 0.09 248.95);
  --ui-chart-4: oklch(0.88 0.09 66.27);
  --ui-chart-5: oklch(0.94 0.14 130.35);
  --ui-sidebar: oklch(0.29 0 0);
  --ui-sidebar-foreground: oklch(0.97 0.01 264.53);
  --ui-sidebar-primary: oklch(0.80 0.14 349.25);
  --ui-sidebar-primary-foreground: oklch(0.22 0 0);
  --ui-sidebar-accent: oklch(0.83 0.09 248.95);
  --ui-sidebar-accent-foreground: oklch(0.22 0 0);
  --ui-sidebar-border: oklch(0.39 0 0);
  --ui-sidebar-ring: oklch(0.83 0.09 248.95);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Gabriela', ui-serif, serif;
  --ui-font-heading: 'Gabriela', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Geist Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 2px 5px 0px oklch(0.83 0.09 248.95  / 0.05);
  --ui-shadow-panel:
    0px 2px 5px 0px oklch(0.83 0.09 248.95  / 0.10), 0px 4px 6px -1px oklch(0.83 0.09 248.95  / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
